const dealProducts = `-- name: DealProducts :many
SELECT
    p.slug,
    localized_name(p.name, p.name_en, $1::text) AS name,
    coalesce(localized_name(p.summary, p.summary_en, $1::text), '')::text AS summary,
    b.name AS brand,
    mv.price_cents AS min_price_cents,
    -- Whether that price is the cheapest of several, so a card can say "from"
    -- rather than state one variant's price as the product's.
    EXISTS (
        SELECT 1 FROM product_variants dv
        WHERE dv.product_id = p.id AND dv.is_active AND dv.price_cents > mv.price_cents
    ) AS price_varies,
    mv.compare_at_price_cents,
    coalesce(rv.rating, 0)::float8 AS rating,
    coalesce(rv.n, 0)::bigint AS rating_count,
    EXISTS (
        SELECT 1 FROM product_variants sv
        WHERE sv.product_id = p.id AND sv.is_active
          AND sv.stock_quantity > sv.safety_stock
    ) AS in_stock,
    coalesce(img.storage_key, '') AS image_key,
    coalesce(localized_name(img.alt_text, img.alt_text_en, $1::text), '')::text AS image_alt,
    coalesce(img.width, 0)::integer AS image_width,
    coalesce(img.height, 0)::integer AS image_height
FROM products p
JOIN brands b ON b.id = p.brand_id
JOIN LATERAL (
    SELECT price_cents, compare_at_price_cents
    FROM product_variants
    WHERE product_id = p.id AND is_active
    ORDER BY (stock_quantity > safety_stock) DESC, price_cents
    LIMIT 1
) mv ON true
LEFT JOIN LATERAL (
    SELECT avg(rating)::float8 AS rating, count(*) AS n
    FROM visible_reviews WHERE product_id = p.id
) rv ON true
LEFT JOIN LATERAL (
    SELECT storage_key, alt_text, alt_text_en, width, height
    FROM product_images WHERE product_id = p.id ORDER BY position LIMIT 1
) img ON true
WHERE p.status = 'active'
  AND EXISTS (
      SELECT 1 FROM product_variants dv
      WHERE dv.product_id = p.id AND dv.is_active
        AND dv.compare_at_price_cents IS NOT NULL
        AND dv.compare_at_price_cents > dv.price_cents
  )
ORDER BY
    -- Deepest discount first, as a fraction rather than an amount.
    ((mv.compare_at_price_cents - mv.price_cents)::float8
     / nullif(mv.compare_at_price_cents, 0)) DESC NULLS LAST,
    p.published_at DESC, p.id DESC
LIMIT $3::integer OFFSET $2::integer
`

type DealProductsParams struct {
	Locale     string
	PageOffset int32
	PageSize   int32
}

type DealProductsRow struct {
	Slug                string
	Name                string
	Summary             string
	Brand               string
	MinPriceCents       int64
	PriceVaries         bool
	CompareAtPriceCents pgtype.Int8
	Rating              float64
	RatingCount         int64
	InStock             bool
	ImageKey            string
	ImageAlt            string
	ImageWidth          int32
	ImageHeight         int32
}

// "On sale" is a variant fact, and a product qualifies when any active variant
// carries one.
func (q *Queries) DealProducts(ctx context.Context, arg DealProductsParams) ([]DealProductsRow, error) {
	rows, err := q.db.Query(ctx, dealProducts, arg.Locale, arg.PageOffset, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DealProductsRow{}
	for rows.Next() {
		var i DealProductsRow
		if err := rows.Scan(
			&i.Slug,
			&i.Name,
			&i.Summary,
			&i.Brand,
			&i.MinPriceCents,
			&i.PriceVaries,
			&i.CompareAtPriceCents,
			&i.Rating,
			&i.RatingCount,
			&i.InStock,
			&i.ImageKey,
			&i.ImageAlt,
			&i.ImageWidth,
			&i.ImageHeight,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

