const returnQueue = `-- name: ReturnQueue :many
SELECT r.id, r.status, r.reason, r.created_at, r.decided_at,
       o.order_number,
       (SELECT coalesce(sum(rl.quantity), 0) FROM return_request_lines rl
        WHERE rl.return_request_id = r.id)::integer AS units,
       return_refundable_amount(r.id)::bigint AS refundable_cents,
       (CASE
            WHEN d.delivered_at IS NULL THEN 'undelivered'
            WHEN r.created_at::date <= d.delivered_at::date + 7 THEN 'within'
            ELSE 'after'
        END)::text AS rescission_window
FROM return_requests r
JOIN orders o ON o.id = r.order_id
LEFT JOIN LATERAL (
    SELECT max(s.delivered_at) AS delivered_at
    FROM order_shipments s WHERE s.order_id = o.id
) d ON true
ORDER BY (r.status = 'requested') DESC, r.created_at DESC
LIMIT $1
`

type ReturnQueueRow struct {
	ID               uuid.UUID
	Status           string
	Reason           string
	CreatedAt        time.Time
	DecidedAt        pgtype.Timestamptz
	OrderNumber      string
	Units            int32
	RefundableCents  int64
	RescissionWindow string
}

// rescission_window: Consumer Protection Act §19 I runs seven days from RECEIPT,
// Civil Code §120 II excludes the day of receipt, and §19 IV fixes the moment on
// the customer's side — so created_at against delivered_at, both database
// clocks. Undelivered is neither answer, because the window has not started.
func (q *Queries) ReturnQueue(ctx context.Context, limit int32) ([]ReturnQueueRow, error) {
	rows, err := q.db.Query(ctx, returnQueue, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReturnQueueRow{}
	for rows.Next() {
		var i ReturnQueueRow
		if err := rows.Scan(
			&i.ID,
			&i.Status,
			&i.Reason,
			&i.CreatedAt,
			&i.DecidedAt,
			&i.OrderNumber,
			&i.Units,
			&i.RefundableCents,
			&i.RescissionWindow,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

