const revokeStaff = `-- name: RevokeStaff :execrows
WITH admins AS (
    SELECT u.id AS admin_id FROM users u WHERE u.role = 'admin' FOR UPDATE
)
UPDATE users SET role = 'customer'
WHERE users.id = $1
  AND users.role IN ('staff', 'admin')
  AND (users.role <> 'admin' OR (SELECT count(*) FROM admins) > 1)
`

// Take somebody's back-office access away. The role goes back to 'customer'
// rather than the row being deleted: erase_user is the only door that removes
// a person.
// The last admin cannot be revoked, and the count is taken INSIDE the statement
// that revokes. Read separately it is a race two admins both pass: each sees
// two, each writes, and the shop is left with none and no way back — the state
// /admin/staff exists to make impossible. Reproduced against a scratch database
// before this was one statement.
//
// FOR UPDATE on the admin rows, so the second statement waits for the first to
// commit and then counts what is actually left rather than what was there when
// it started.
func (q *Queries) RevokeStaff(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, revokeStaff, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rootCategories = `-- name: RootCategories :many
SELECT id, slug, localized_name(name, name_en, $1::text) AS name, icon_key
FROM categories
WHERE parent_id IS NULL
ORDER BY position, name, id
`

type RootCategoriesRow struct {
	ID      uuid.UUID
	Slug    string
	Name    string
	IconKey pgtype.Text
}

// A query rather than a list in Go: a category has one name and one place it is
// translated, and a second copy in the header drifts from the catalogue.
// The header's row AND the home page's tiles: the same six rows in the same
// order, because two queries answering "in what order are the categories" gave
// two answers the moment CreateCategory's max(position)+1 handed out a
// duplicate. Nothing stops it: there is no unique index on (parent_id,
// position), so two staff creating a category at once both read the same max.
func (q *Queries) RootCategories(ctx context.Context, locale string) ([]RootCategoriesRow, error) {
	rows, err := q.db.Query(ctx, rootCategories, locale)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RootCategoriesRow{}
	for rows.Next() {
		var i RootCategoriesRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.IconKey,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

